 	struct percpu_ref ref;
-	struct list_head list;
 	struct rcu_head rcu_head;
 	struct work_struct release_work;
 	struct hlist_node node;
+	u8 idx;
 	char tfm_name[CRYPTO_MAX_ALG_NAME];
